mapper.select:
SELECT

FROM UserCertKyc a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.surName = #{surName}


    AND a.realName = #{realName}


    AND a.region = #{region}


    AND a.passportType = #{passportType}


    AND a.passportNo = #{passportNo}


    AND a.passportImg1 = #{passportImg1}


    AND a.passportImg2 = #{passportImg2}


    AND a.passportImg3 = #{passportImg3}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}


    AND a.checkBy = #{checkBy}


    AND a.checkTime = #{checkTime}

limit 1
